python3 << 'EOF'
import json

with open('/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0513-projects-occsafe-vla/4161c3ca-c044-4dc8-b7b5-7c1b6b995256/tool-results/mcp-agent-ml-research-read_registry-1779663325215.txt', 'r') as f:
    raw = json.load(f)

data = json.loads(raw['result'])
experiments = data['data']['experiments']

# Now comprehensive analysis
# Director-named experiments
director_names = ['cutoff_15k_s0', 'cutoff_25k_s0', 'cutoff_45k_s0', 'reverse_cutoff_s0', 'cutoff_s0', 'cutoff_s1', 'detach_ln_s0', 'detach_ln_s1', 'detach_ln_s2']

# Build list of all eval experiments and their metrics
eval_map = {}  # parent_id -> {eval_exp_id, CAR, TSR}
for exp_id, exp in experiments.items():
    if 'eval' not in exp_id:
        continue
    if exp.get('status') != 'DONE' or exp.get('conclusion') != 'success':
        continue
    parent = exp.get('parent', '')
    metrics = exp.get('metrics', {})

    car = metrics.get('CAR') or metrics.get('overall_car')
    tsr = metrics.get('TSR') or metrics.get('overall_tsr')

    if parent and (car is not None or tsr is not None):
        if parent not in eval_map:
            eval_map[parent] = []
        eval_map[parent].append({
            'eval_exp_id': exp_id,
            'CAR': car,
            'TSR': tsr
        })

# Also check if training experiment itself has metrics (like occ_s1_fresh)
train_with_metrics = {}
for exp_id, exp in experiments.items():
    if 'eval' in exp_id:
        continue
    if exp.get('status') != 'DONE' or exp.get('conclusion') != 'success':
        continue
    metrics = exp.get('metrics', {})
    if metrics:
        # Check for CAR/TSR at any level
        metrics_str = json.dumps(metrics)
        if 'CAR' in metrics_str or 'car' in metrics_str:
            train_with_metrics[exp_id] = metrics

print("=== EVAL MAP (parent -> eval results) ===")
for parent, evals in sorted(eval_map.items()):
    print(f"  {parent} -> {evals}")

print(f"\n=== TRAINING EXPERIMENTS WITH EMBEDDED METRICS ===")
for exp_id in train_with_metrics:
    m = train_with_metrics[exp_id]
    # Extract top-level or nested CAR/TSR
    car = m.get('CAR') or m.get('overall_car')
    tsr = m.get('TSR') or m.get('overall_tsr')
    if car is None:
        # Check nested
        for k, v in m.items():
            if isinstance(v, dict):
                car = v.get('CAR') or v.get('overall_car')
                tsr = v.get('TSR') or v.get('overall_tsr')
                if car:
                    print(f"  {exp_id}: CAR={car}, TSR={tsr} (from {k})")
                    break
    else:
        print(f"  {exp_id}: CAR={car}, TSR={tsr}")
EOF
